import React, { useState, useEffect } from 'react';
// Cambié el nombre del archivo para hacerlo más específico

function BD({ apiCentral }) {
  const [data, setData] = useState([]);

  useEffect(() => {
    fetch(`${apiCentral}/api/get/restaurant`)
      .then(res => res.json())
      .then(date => setData(date));
  }, [apiCentral]);

  return (
    <div className="dashboard-restaurantes-container">
      <h2 className="dashboard-restaurantes-title">Lista de Restaurantes Activos</h2>
      <table className="restaurantes-data-table">
        <thead>
          <tr>
            <th style={{ textAlign: 'center' }}>Nombre Restaurante</th>
            <th style={{ textAlign: 'center' }}>Plan</th>
            <th style={{ textAlign: 'center' }}>Número Servicio</th>
            <th style={{ textAlign: 'center' }}>Fecha Pago</th>
            <th style={{ textAlign: 'center' }}>Nombre Responsable</th>
            <th style={{ textAlign: 'center' }}>Tamaño Restaurante</th>
            <th style={{ textAlign: 'center' }}>Número Mesas</th>
            <th style={{ textAlign: 'center' }}>Dominio</th>
          </tr>
        </thead>
        <tbody>
          {data.map((restaurant, index) => (
            <tr key={index}>
              <td style={{ textAlign: 'center' }}>{restaurant.nombreRestaurante}</td>
              <td style={{ textAlign: 'center' }}>{restaurant.plan}</td>
              <td style={{ textAlign: 'center' }}>{restaurant.numeroServicio}</td>
              <td style={{ textAlign: 'center' }}>{restaurant.fechaPago}</td>
              <td style={{ textAlign: 'center' }}>{restaurant.nombreResponsable}</td>
              <td style={{ textAlign: 'center' }}>{restaurant.tamanoRestaurante}</td>
              <td style={{ textAlign: 'center' }}>{restaurant.numeroMesas}</td>
              <td style={{ textAlign: 'center' }}>{restaurant.dominio}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default BD;
